import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import com.wolinski.shop.customers.api.CustomerFacade;
import com.wolinski.shop.notifications.api.Notifier;
import com.wolinski.shop.orders.api.OrderCancelled;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import org.junit.jupiter.api.Test;

class CancellationNotificationsTest {

    private final List<String> sent = new ArrayList<>();
    private final Notifier notifier = (address, subject, body) -> sent.add(address + "|" + subject);
    private final CustomerFacade customers = new CustomerFacade() {
        private final Map<String, String> emails = Map.of("c-1", "anna@shop.example");

        @Override
        public void register(String customerId, String email) {
        }

        @Override
        public String emailOf(String customerId) {
            return emails.get(customerId);
        }
    };

    @Test
    void theCustomerGetsOneMailWithTheOrderIdInTheSubject() {
        new CancellationNotifications(notifier, customers).on(new OrderCancelled("o-42", "c-1"));

        assertEquals(List.of("anna@shop.example|Order o-42 cancelled"), sent);
    }

    @Test
    void nothingIsSentWhenTheCustomerHasNoRegisteredAddress() {
        new CancellationNotifications(notifier, customers).on(new OrderCancelled("o-42", "c-unknown"));

        assertTrue(sent.isEmpty());
    }
}
}

